package com.pipican.boss;
import java.util.*;import net.minecraft.core.particles.ParticleTypes;import net.minecraft.server.level.ServerLevel;import net.minecraft.sounds.SoundEvents;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.entity.player.Player;import net.minecraft.world.entity.projectile.Projectile;import net.minecraft.world.level.storage.ValueInput;import net.minecraft.world.level.storage.ValueOutput;import net.minecraft.world.phys.Vec3;
/** Sequential spore refuges, interruptible healing seedlings, and a locked bloom cone. */
public final class SyltheraCombat{
 public static final String SPORES="spore_sequence",NURSERY="root_nursery",BLOOM="bloom_inhalation";private final RegionalBossEntity boss;private final RegionalCombatClock clock;private Vec3 origin=Vec3.ZERO,mark=Vec3.ZERO;private double heading;private List<Boolean> cleared=List.of(false,false,false);private int phase=1,safeRing=0,sequence=0;
 public SyltheraCombat(RegionalBossEntity b){boss=b;var d=BossDesigns.require("sylthera_primordial_bloom");clock=new RegionalCombatClock(Map.of(SPORES,time(d,0),NURSERY,time(d,1),BLOOM,time(d,2),"basic",new RegionalCombatClock.Timing(18,20,55)));}private static RegionalCombatClock.Timing time(BossDesigns.Design d,int i){var a=d.abilities().get(i);return new RegionalCombatClock.Timing(a.windup(),a.recovery(),a.cooldown());}
 public RegionalCombatClock clock(){return clock;}public int clearedSeedlings(){return(int)cleared.stream().filter(Boolean::booleanValue).count();}public int safeRing(){return safeRing;}public Vec3 ringPoint(int i){if(i<0||i>=3)throw new IndexOutOfBoundsException();double a=heading+i*2*Math.PI/3;return origin.add(Math.cos(a)*7,0,Math.sin(a)*7);}public Vec3 safeSporePosition(){double a=heading+Math.PI/2,r=3.1+safeRing*2.2;return origin.add(Math.cos(a)*r,0,Math.sin(a)*r);}public Vec3 seedling(int i){return ringPoint(i);}public Vec3 bloomPoint(int n){return cone().get(Math.clamp(n,0,cone().size()-1));}
 public boolean begin(String id,LivingEntity t){if(t==null||!t.isAlive()||!boss.insideArena(t.position())||!clock.begin(id))return false;origin=boss.position();mark=t.position();heading=Math.atan2(mark.z-origin.z,mark.x-origin.x);phase=clock.phase();if(phase==2){safeRing=(safeRing+1)%3;sequence=(sequence+1)%3;boss.playSound(SoundEvents.SPORE_BLOSSOM_FALL,1.1f,.8f);}if(id.equals(NURSERY))cleared=List.of(false,false,false);return true;}
 private List<Vec3> circle(double radius){var p=new ArrayList<Vec3>();for(int a=0;a<360;a+=8){double r=Math.toRadians(a);Vec3 q=origin.add(Math.cos(r)*radius,0,Math.sin(r)*radius);if(boss.insideArena(q))p.add(q);}return p;}
 private List<Vec3> cone(){var p=new ArrayList<Vec3>();for(int n=2;n<=13;n++)for(int s=-2;s<=2;s++){double a=heading+s*.12;Vec3 q=origin.add(Math.cos(a)*n,0,Math.sin(a)*n);if(boss.insideArena(q))p.add(q);}return p;}
 private List<Vec3> segment(Vec3 a,Vec3 b){var p=new ArrayList<Vec3>();for(int i=0;i<=20;i++){Vec3 q=a.lerp(b,i/20.0);if(boss.insideArena(q))p.add(q);}return p;}
 public void tick(ServerLevel l){String id=clock.active();if(id.equals(NURSERY)&&!clock.resolved())checkSeedlings(l);if(!id.isEmpty()&&!clock.resolved()&&clock.remaining()%5==0)telegraph(l,id);if(id.isEmpty()){clock.tick();return;}String impact=clock.tick();if(impact.isEmpty())return;switch(impact){case SPORES->{for(int i=0;i<3;i++)if(i!=safeRing)strike(l,circle(3.1+i*2.2),.34f);boss.playSound(SoundEvents.SPORE_BLOSSOM_FALL,1.1f,.7f);}case NURSERY->{for(int i=0;i<3;i++)if(!cleared.get(i))strike(l,circleAt(seedling(i),2.2),.48f);if(clearedSeedlings()==0)boss.heal(Math.min(18,boss.getMaxHealth()-boss.getHealth()));boss.playSound(SoundEvents.ROOTED_DIRT_PLACE,1f,.8f);}case BLOOM->{strike(l,cone(),.62f);boss.playSound(SoundEvents.BREEZE_WIND_CHARGE_BURST.value(),1.1f,.7f);}case "basic"->strike(l,List.of(mark),.68f);default->{}}}
 private List<Vec3> circleAt(Vec3 c,double radius){var p=new ArrayList<Vec3>();for(int a=0;a<360;a+=12){double r=Math.toRadians(a);Vec3 q=c.add(Math.cos(r)*radius,0,Math.sin(r)*radius);if(boss.insideArena(q))p.add(q);}return p;}
 private void checkSeedlings(ServerLevel l){var n=new ArrayList<>(cleared);for(int i=0;i<3;i++)if(!n.get(i)){Vec3 p=seedling(i);var shots=l.getEntitiesOfClass(Projectile.class,new net.minecraft.world.phys.AABB(p.add(-1,-1,-1),p.add(1,1.5,1)),Projectile::isAlive);if(!shots.isEmpty()){n.set(i,true);shots.forEach(Projectile::discard);l.sendParticles(ParticleTypes.POOF,p.x,p.y,p.z,14,.25,.2,.25,.02);}}cleared=List.copyOf(n);}
 private void telegraph(ServerLevel l,String id){if(id.equals(SPORES)){for(int i=0;i<3;i++)for(Vec3 p:circle(3.1+i*2.2))if((int)(p.x+p.z)%4==0)l.sendParticles(i==safeRing?ParticleTypes.HAPPY_VILLAGER:ParticleTypes.SPORE_BLOSSOM_AIR,p.x,p.y+.15,p.z,1,.03,.03,.03,0);}else if(id.equals(NURSERY)){for(int i=0;i<3;i++){Vec3 p=seedling(i);l.sendParticles(cleared.get(i)?ParticleTypes.POOF:ParticleTypes.HAPPY_VILLAGER,p.x,p.y+.2,p.z,9,.2,.2,.2,0);for(Vec3 q:circleAt(p,2.2))if((int)(q.x+q.z)%3==0)l.sendParticles(ParticleTypes.COMPOSTER,q.x,q.y+.1,q.z,1,.02,.02,.02,0);}}else for(Vec3 p:cone())if((int)(p.x+p.z)%3==0)l.sendParticles(ParticleTypes.SPORE_BLOSSOM_AIR,p.x,p.y+.2,p.z,1,.03,.03,.03,0);}
 private void strike(ServerLevel l,List<Vec3> points,float scale){for(Player p:l.getEntitiesOfClass(Player.class,boss.getBoundingBox().inflate(28),q->q.isAlive()&&!q.isCreative()&&!q.isSpectator()&&boss.insideArena(q.position())))if(points.stream().anyMatch(q->Math.abs(q.y-p.getY())<3&&q.distanceToSqr(p.position())<1.8*1.8))p.hurtServer(l,boss.damageSources().mobAttack(boss),(float)(boss.getAttributeValue(Attributes.ATTACK_DAMAGE)*scale));}
 public boolean updatePhase(float hp,float max){boolean c=clock.updatePhase(hp,max);if(c)phase=2;return c;}public void save(ValueOutput o){clock.save(o);o.store("SyltheraOrigin",Vec3.CODEC,origin);o.store("SyltheraMark",Vec3.CODEC,mark);o.store("SyltheraCleared",com.mojang.serialization.Codec.BOOL.listOf(),cleared);o.putDouble("SyltheraHeading",heading);o.putInt("SyltheraPhase",phase);o.putInt("SyltheraSafeRing",safeRing);o.putInt("SyltheraSequence",sequence);}public void load(ValueInput i){clock.load(i);origin=i.read("SyltheraOrigin",Vec3.CODEC).orElse(Vec3.ZERO);mark=i.read("SyltheraMark",Vec3.CODEC).orElse(Vec3.ZERO);cleared=i.read("SyltheraCleared",com.mojang.serialization.Codec.BOOL.listOf()).orElse(List.of(false,false,false)).stream().limit(3).toList();if(cleared.size()<3){var n=new ArrayList<>(cleared);while(n.size()<3)n.add(false);cleared=List.copyOf(n);}heading=i.getDoubleOr("SyltheraHeading",0);phase=clock.phase();safeRing=Math.floorMod(i.getIntOr("SyltheraSafeRing",0),3);sequence=Math.floorMod(i.getIntOr("SyltheraSequence",0),3);}
}
